                if p in unseen and grid[p[0]][p[1]] == color:
                    unseen.remove(p); cells.add(p); q.append(p)
        r0=min(r for r,c in cells); r1=max(r for r,c in cells)
        c0=min(c for r,c in cells); c1=max(c for r,c in cells)
        mask=frozenset((r-r0,c-c0) for r,c in cells)
        # A zero region wholly enclosed by the object's bounding box is a hole.
        box={(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)}
        zeros=box-cells
        hole=False
        while zeros:
            start=zeros.pop(); region={start}; q=[start]; touches=False
            while q:
                r,c=q.pop()
                if r in (r0,r1) or c in (c0,c1): touches=True
                for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if p in zeros:
                        zeros.remove(p); region.add(p); q.append(p)
            if not touches:
                hole=True
        objs.append({'color':color,'cells':cells,'r0':r0,'r1':r1,'c0':c0,'c1':c1,'mask':mask,'hole':hole})
    # Enclosed-hole shapes rise; solid shapes fall.
    for o in objs:
        o['dir']=-1 if o['hole'] else 1
    placed=[]
    # Move top-bound objects first, then bottom-bound objects, avoiding collisions.
    ordered=sorted((o for o in objs if o['dir']<0), key=lambda o:o['r0']) + sorted((o for o in objs if o['dir']>0), key=lambda o:-o['r1'])
